import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BsgK4TUM.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/installation.md","filePath":"user-guide/installation.md"}'),r={name:"user-guide/installation.md"};function i(s,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Concrete CMS 8.5 or higher</li><li>PHP 7.4 or higher</li></ul><p>Community Store is an <em>add on</em> for the content management system Concrete CMS, so it is not a stand-alone shopping cart. It is recommended to use a release of Community Store, rather than the master branch.</p><h2 id="downloading" tabindex="-1">Downloading <a class="header-anchor" href="#downloading" aria-label="Permalink to &quot;Downloading&quot;">​</a></h2><p>The latest release of Community Store should be downloaded from the <a href="https://github.com/concretecms-community-store/community_store/releases" target="_blank" rel="noreferrer">releases section of the project on github</a>.</p><h2 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h2><p>The <code>community_store</code> package folder is placed within the top level <code>packages</code> folder and Community Store is installed via the <strong>Extend</strong> section of the Dashboard.</p><p>During installation you can choose the page template used for the Product page type, and whether to create a parent page (and where) for product pages to be published under.</p><p>Once installed, the Dashboard page <strong>Store / Settings</strong> should be visited to configure default settings such the store&#39;s currency, notification emails, shipping units and checkout modes. Refer to the <a href="/community_store/user-guide/configuration.html">Initial Setup</a> documentation as to a recommended set of options to review.</p><h2 id="updating" tabindex="-1">Updating <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;Updating&quot;">​</a></h2><p>To update Community Store, completely replace the <code>community_store</code> folder and immediately trigger the upgrade of the add-on via the <strong>Extend</strong> section of the Dashboard. When replacing the add-on&#39;s folder, do not rename and leave the previous version of the folder within the packages directory - this will cause errors.</p><h2 id="installing-related-add-ons" tabindex="-1">Installing Related Add-ons <a class="header-anchor" href="#installing-related-add-ons" aria-label="Permalink to &quot;Installing Related Add-ons&quot;">​</a></h2><p>Related add-ons such as additional payment or shipping methods are installed in the same manner. Refer to the <a href="https://github.com/concretecms-community-store" target="_blank" rel="noreferrer">top level Community Store page on github</a> for additional add-ons. Where possible, also install releases of the add-ons instead of downloading the <em>master</em> branches.</p>',14)])])}const p=t(r,[["render",i]]);export{u as __pageData,p as default};
